def pyramide(quiz=False, w=150):
    """Pyramide inversée de l'article de presse."""
    rows = [("L'ESSENTIEL", "qui ? quoi ? où ? quand ?", "#3F5866"), ("LES DÉTAILS IMPORTANTS", "comment ? pourquoi ? (explications, témoignages)", "#6C8A99"), ("LE CONTEXTE", "l'historique, les chiffres", "#9FB4BF"), ("le moins important", "", "#CFDAE0")]
    out = ""
    for i, (t, d, c) in enumerate(rows):
        x = 6 + i * 22
        out += f'<polygon points="{x},{6 + i * 26} {200 - x},{6 + i * 26} {200 - x - 22},{30 + i * 26} {x + 22},{30 + i * 26}" fill="{c}"/>'
        out += f'<text x="100" y="{17 + i * 26}" font-size="{7.5 if i < 3 else 6}" text-anchor="middle" fill="#fff" font-weight="700">{"…………" if quiz and i < 3 else t}</text><text x="100" y="{25.5 + i * 26}" font-size="5.6" text-anchor="middle" fill="#fff">{"" if quiz else d}</text>'
    return f'<svg viewBox="0 0 200 112" width="{w}mm" style="max-width:100%;display:block;margin:0 auto" font-family="Poppins">{out}</svg>'


def fil(posts, w=182):
    """Fil d'actualité : posts = [(lettre, compte, badge, texte, extra)]."""
    out = ""
    for k, acc, badge, t, ex in posts:
        out += (f'<div style="background:#fff;border:1px solid #d7dbe3;border-radius:2.5mm;padding:1.5mm 2.5mm;margin-bottom:1.3mm"><div class="flex" style="gap:2mm;justify-content:space-between"><span><b style="color:#E4572E">{k}</b> <b>{acc}</b> <span class="xs muted">{badge}</span></span><span class="xs muted">{ex}</span></div>'
                f'<div class="sm" style="margin-top:.6mm">{t}</div></div>')
    return f'<div style="background:#F2F4F7;border-radius:3mm;padding:2mm;width:{w}mm;max-width:100%">{out}</div>'


def chemin(n=8, labels=None):
    """Chemin de fer : plan des pages d'un journal."""
    labels = labels or [""] * n
    return '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:2mm">' + "".join(f'<div style="border:1.5px solid {MC};border-radius:1.5mm;height:34mm;padding:1mm 1.5mm;position:relative;background:#fff"><span class="xs" style="position:absolute;top:.5mm;right:1.5mm;color:{MC};font-weight:800">p. {i + 1}</span><span class="xs">{labels[i]}</span></div>' for i in range(n)) + '</div>'


def barres(data, w=170, unit="élèves"):
    """Diagramme en barres horizontales (sondage de la classe)."""
    mx = max(v for _, v in data)
    rows = "".join(f'<div class="flex" style="gap:2mm;margin-bottom:1mm"><span class="xs" style="width:42mm;text-align:right">{t}</span><div style="height:5mm;width:{v / mx * 100:.0f}mm;background:{MC};border-radius:1mm"></div><b class="xs">{v}</b></div>' for t, v in data)
    return f'<div style="width:{w}mm;max-width:100%">{rows}<div class="xs muted" style="margin-left:44mm">nombre d\'{unit}</div></div>'


